/** Return the options available at one level of a tree for the supplied path. */
export function getTreeOptions(tree, path, level) {
	let node = tree;
	for (let i = 0; i < level; i++) {
		if (!node || Array.isArray(node)) return [];
		node = node[path[i]];
	}
	if (!node) return [];
	return Array.isArray(node) ? node : Object.keys(node);
}

/**
 * Complete a partial tree path down to a leaf. Invalid/missing descendants are
 * replaced by the first option in their level. This is especially important
 * when switching branches, because descendants from the previous branch no
 * longer belong to the newly selected one.
 */
export function completeTreePath(tree, partialPath = []) {
	const requested = Array.isArray(partialPath) ? partialPath : [];
	const result = [];
	let node = tree;
	let level = 0;

	while (node) {
		const options = Array.isArray(node) ? node : Object.keys(node);
		if (!options.length) break;
		const requestedOption = requested[level];
		const option = options.includes(requestedOption) ? requestedOption : options[0];
		result.push(option);

		if (Array.isArray(node)) break;
		node = node[option];
		level++;
	}

	return result;
}

export function treePathsEqual(a, b) {
	return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((value, index) => value === b[index]);
}

/** Return a complete path with the sibling at `level` moved left/right. */
export function moveTreePath(tree, path, level, direction) {
	const completePath = completeTreePath(tree, path);
	const options = getTreeOptions(tree, completePath, level);
	const currentIndex = options.indexOf(completePath[level]);
	if (currentIndex < 0) return null;

	const offset = direction === 'left' ? -1 : 1;
	const nextIndex = currentIndex + offset;
	if (nextIndex < 0 || nextIndex >= options.length) return null;

	return completeTreePath(tree, [...completePath.slice(0, level), options[nextIndex]]);
}
