/**
 * Shared contract version between DynamicMenu and CanvasRenderer.
 *
 * DynamicMenu produces state snapshots (`getMenuState()`) and events
 * (`subscribe()`); CanvasRenderer consumes them. The two classes can ship as
 * separate files/bundles, so a build of one may be paired with a mismatched
 * build of the other. What actually has to agree is not their *implementation*
 * version but the *shape* of the snapshots and events they exchange — that is
 * what this constant versions.
 *
 * Bump it ONLY when that shared shape changes:
 *   - major ("2.0"): breaking change (field renamed/removed, event reshaped) →
 *                    the consumer cannot safely interpret the data → throw.
 *   - minor ("1.1"): backward-compatible addition (new optional field/event) →
 *                    older consumer keeps working → warn so builds get realigned.
 *
 * Pure internal changes (faster drawing, refactors) must NOT bump this.
 *
 * @type {string}
 */
export const PROTOCOL_VERSION = '1.0';

/**
 * Parse a protocol version into comparable parts. Accepts the legacy numeric
 * form (`1`) as well as the dotted string form (`'1.0'`).
 * @param {string|number|null|undefined} v
 * @returns {{ major: string, minor: string, raw: string } | null} null if absent.
 */
export function parseProtocol(v) {
	if (v === undefined || v === null || v === '') return null;
	const raw = String(v);
	const [major, minor = '0'] = raw.split('.');
	return { major, minor, raw };
}

/**
 * Compare a producer's protocol version against this build's PROTOCOL_VERSION.
 *
 * @param {string|number|null|undefined} theirVersion - Version stamped on the
 *   incoming snapshot/event (`state.version`).
 * @returns {{ level: 'ok'|'minor'|'major'|'unknown', message: string }}
 *   - `ok`:      same version, nothing to report.
 *   - `minor`:   same major, different minor → compatible, caller should warn.
 *   - `major`:   different major → incompatible, caller should throw.
 *   - `unknown`: no version present → likely a legacy/foreign producer; warn.
 */
export function checkProtocol(theirVersion) {
	const mine = parseProtocol(PROTOCOL_VERSION);
	const theirs = parseProtocol(theirVersion);

	if (!theirs) {
		return {
			level: 'unknown',
			message:
				`[DynamicMenu↔CanvasRenderer] incoming state has no protocol version; ` +
				`expected ${PROTOCOL_VERSION}. Assuming legacy/compatible, but the producer ` +
				`is likely older than this CanvasRenderer build.`,
		};
	}

	if (theirs.major !== mine.major) {
		return {
			level: 'major',
			message:
				`[DynamicMenu↔CanvasRenderer] incompatible protocol versions: ` +
				`DynamicMenu state=${theirs.raw}, CanvasRenderer=${PROTOCOL_VERSION}. ` +
				`The major version differs — the snapshot/event shape is not compatible. ` +
				`Use builds of DynamicMenu and CanvasRenderer that share the same major version.`,
		};
	}

	if (theirs.raw !== mine.raw) {
		return {
			level: 'minor',
			message:
				`[DynamicMenu↔CanvasRenderer] protocol minor mismatch: ` +
				`DynamicMenu state=${theirs.raw}, CanvasRenderer=${PROTOCOL_VERSION}. ` +
				`Backward-compatible, but you should align both builds.`,
		};
	}

	return { level: 'ok', message: '' };
}
